const CHECK_SVG =
  '<svg class="check-mark" viewBox="0 0 16 16" aria-hidden="true"><path d="M2.5 8.5l3.5 3.5 7-8" fill="none" stroke="#ffffff" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>';

const els = {
  todayLabel: document.querySelector('[data-role="today-label"]'),
  doneCount: document.querySelector('[data-role="done-count"]'),
  totalCount: document.querySelector('[data-role="total-count"]'),
  progressFill: document.querySelector('[data-role="progress-fill"]'),
  addForm: document.querySelector('[data-role="add-form"]'),
  habitInput: document.querySelector('[data-role="habit-input"]'),
  addError: document.querySelector('[data-role="add-error"]'),
  listError: document.querySelector('[data-role="list-error"]'),
  habitList: document.querySelector('[data-role="habit-list"]'),
  emptyState: document.querySelector('[data-role="empty-state"]'),
  dialogMask: document.querySelector('[data-role="dialog-mask"]'),
  dialogText: document.querySelector('[data-role="dialog-text"]'),
  dialogCancel: document.querySelector('[data-role="dialog-cancel"]'),
  dialogConfirm: document.querySelector('[data-role="dialog-confirm"]')
};

let state = null;
let pendingDeleteId = null;

function todayKey() {
  const d = new Date();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return d.getFullYear() + "-" + m + "-" + day;
}

function formatTodayLabel() {
  const d = new Date();
  const week = ["星期日", "星期一", "星期二", "星期三", "星期四", "星期五", "星期六"];
  return (
    d.getFullYear() + " 年 " + (d.getMonth() + 1) + " 月 " + d.getDate() + " 日 · " + week[d.getDay()]
  );
}

function normalizeHabit(raw) {
  const source = raw && typeof raw === "object" ? raw : {};
  const habit = Object.assign({}, source);
  if (typeof habit.id !== "string" || habit.id === "") {
    habit.id = "h_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 8);
  }
  if (typeof habit.name !== "string") {
    habit.name = String(habit.name == null ? "" : habit.name);
  }
  if (!habit.doneDates || typeof habit.doneDates !== "object" || Array.isArray(habit.doneDates)) {
    habit.doneDates = {};
  }
  if (typeof habit.createdAt !== "number") {
    habit.createdAt = Date.now();
  }
  return habit;
}

function normalizeState(raw) {
  const source = raw && typeof raw === "object" ? raw : {};
  const next = Object.assign({}, source);
  const list = Array.isArray(source.habits) ? source.habits : [];
  next.habits = list.map(normalizeHabit);
  return next;
}

function showError(el, message) {
  if (!message) {
    el.hidden = true;
    el.textContent = "";
    return;
  }
  el.hidden = false;
  el.textContent = message;
}

function isDoneToday(habit) {
  return habit.doneDates[todayKey()] === true;
}

function render() {
  const habits = state.habits;
  const total = habits.length;
  let done = 0;
  for (const habit of habits) {
    if (isDoneToday(habit)) done += 1;
  }

  els.doneCount.textContent = String(done);
  els.totalCount.textContent = String(total);
  const percent = total === 0 ? 0 : Math.round((done / total) * 100);
  els.progressFill.style.width = percent + "%";

  els.habitList.textContent = "";
  for (const habit of habits) {
    const doneToday = isDoneToday(habit);

    const li = document.createElement("li");
    li.className = "habit-item" + (doneToday ? " is-done" : "");
    li.dataset.habitId = habit.id;

    const checkBtn = document.createElement("button");
    checkBtn.type = "button";
    checkBtn.className = "check-btn";
    checkBtn.dataset.action = "toggle";
    checkBtn.setAttribute("aria-pressed", doneToday ? "true" : "false");
    checkBtn.setAttribute(
      "aria-label",
      (doneToday ? "取消今天完成：" : "标记今天完成：") + habit.name
    );
    checkBtn.innerHTML = CHECK_SVG;

    const name = document.createElement("span");
    name.className = "habit-name";
    name.textContent = habit.name;

    const status = document.createElement("span");
    status.className = "habit-status";
    status.textContent = doneToday ? "今天已完成" : "今天未完成";

    const delBtn = document.createElement("button");
    delBtn.type = "button";
    delBtn.className = "delete-btn";
    delBtn.dataset.action = "delete";
    delBtn.textContent = "删除";
    delBtn.setAttribute("aria-label", "删除习惯：" + habit.name);

    li.appendChild(checkBtn);
    li.appendChild(name);
    li.appendChild(status);
    li.appendChild(delBtn);
    els.habitList.appendChild(li);
  }

  els.emptyState.hidden = total !== 0;
}

async function persist(nextState, errorEl, errorMessage) {
  try {
    await appStore.setState(nextState);
    state = nextState;
    showError(errorEl, "");
    return true;
  } catch (err) {
    showError(errorEl, errorMessage || "保存失败，请重试。");
    return false;
  }
}

async function addHabit(name) {
  const trimmed = name.trim();
  if (trimmed === "") {
    showError(els.addError, "请输入习惯名称。");
    return false;
  }
  if (trimmed.length > 40) {
    showError(els.addError, "习惯名称不能超过 40 个字。");
    return false;
  }

  const habit = normalizeHabit({ name: trimmed });
  const next = Object.assign({}, state, { habits: state.habits.concat([habit]) });
  const ok = await persist(next, els.addError, "保存失败，习惯未添加，请重试。");
  if (ok) {
    els.habitInput.value = "";
    showError(els.addError, "");
    render();
  }
  return ok;
}

async function toggleHabit(id) {
  const index = state.habits.findIndex((h) => h.id === id);
  if (index === -1) return;

  const key = todayKey();
  const habits = state.habits.slice();
  const target = normalizeHabit(habits[index]);
  const doneDates = Object.assign({}, target.doneDates);
  if (doneDates[key] === true) {
    delete doneDates[key];
  } else {
    doneDates[key] = true;
  }
  target.doneDates = doneDates;
  habits[index] = target;

  const next = Object.assign({}, state, { habits: habits });
  const ok = await persist(next, els.listError, "保存失败，打卡状态未更新，请重试。");
  if (ok) {
    render();
  }
}

async function deleteHabit(id) {
  const habits = state.habits.filter((h) => h.id !== id);
  const next = Object.assign({}, state, { habits: habits });
  const ok = await persist(next, els.listError, "保存失败，习惯未删除，请重试。");
  if (ok) {
    render();
  }
}

function openDeleteDialog(id) {
  const habit = state.habits.find((h) => h.id === id);
  if (!habit) return;
  pendingDeleteId = id;
  els.dialogText.textContent = "确定要删除习惯「" + habit.name + "」吗？删除后无法恢复。";
  els.dialogMask.hidden = false;
  els.dialogConfirm.focus();
}

function closeDeleteDialog() {
  pendingDeleteId = null;
  els.dialogMask.hidden = true;
}

async function init() {
  els.todayLabel.textContent = formatTodayLabel();

  let raw = null;
  try {
    raw = await appStore.getState();
  } catch (err) {
    raw = null;
  }

  const source = raw && typeof raw === "object" ? raw : {};
  const hasHabits = Array.isArray(source.habits);
  state = normalizeState(source);

  if (!hasHabits) {
    const seeded = Object.assign({}, state, { habits: [] });
    try {
      await appStore.setState(seeded);
      state = seeded;
    } catch (err) {
      showError(els.listError, "初始化数据失败，当前更改可能无法保存。");
    }
  }

  render();

  els.addForm.addEventListener("submit", async (event) => {
    event.preventDefault();
    await addHabit(els.habitInput.value);
  });

  els.habitInput.addEventListener("input", () => {
    if (!els.addError.hidden) showError(els.addError, "");
  });

  els.habitList.addEventListener("click", async (event) => {
    const btn = event.target.closest("button[data-action]");
    if (!btn) return;
    const item = btn.closest("[data-habit-id]");
    if (!item) return;
    const id = item.dataset.habitId;
    if (btn.dataset.action === "toggle") {
      await toggleHabit(id);
    } else if (btn.dataset.action === "delete") {
      openDeleteDialog(id);
    }
  });

  els.dialogCancel.addEventListener("click", () => {
    closeDeleteDialog();
  });

  els.dialogConfirm.addEventListener("click", async () => {
    const id = pendingDeleteId;
    closeDeleteDialog();
    if (id) await deleteHabit(id);
  });

  els.dialogMask.addEventListener("click", (event) => {
    if (event.target === els.dialogMask) closeDeleteDialog();
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !els.dialogMask.hidden) {
      closeDeleteDialog();
    }
  });
}

await init();

