:root {
  --bg: #f4f6fb;
  --card: #ffffff;
  --text: #1f2733;
  --muted: #6b7688;
  --line: #e3e8f0;
  --primary: #3b6ef6;
  --primary-dark: #2f59cc;
  --success: #17a673;
  --danger: #d64545;
  --shadow: 0 6px 20px rgba(31, 39, 51, 0.08);
}

* {
  box-sizing: border-box;
}

.app-wrap {
  max-width: 560px;
  margin: 0 auto;
  padding: 20px 16px 48px;
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC",
    "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  font-size: 15px;
  line-height: 1.5;
}

.app-header {
  padding: 8px 4px 16px;
}

.app-title {
  margin: 0;
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.app-date {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 13px;
}

.stats-card {
  background: var(--card);
  border-radius: 16px;
  padding: 18px 20px 20px;
  box-shadow: var(--shadow);
  margin-bottom: 16px;
}

.stats-main {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.stats-number {
  font-size: 40px;
  font-weight: 700;
  color: var(--primary);
  line-height: 1;
}

.stats-slash {
  font-size: 22px;
  color: var(--muted);
}

.stats-total {
  font-size: 22px;
  font-weight: 600;
  color: var(--muted);
}

.stats-caption {
  margin: 6px 0 12px;
  color: var(--muted);
  font-size: 13px;
}

.progress-track {
  height: 8px;
  border-radius: 999px;
  background: #eef1f7;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  width: 0;
  border-radius: 999px;
  background: linear-gradient(90deg, #3b6ef6, #17a673);
  transition: width 0.25s ease;
}

.add-card {
  background: var(--card);
  border-radius: 16px;
  padding: 16px 20px 18px;
  box-shadow: var(--shadow);
  margin-bottom: 20px;
}

.field-label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--muted);
  margin-bottom: 8px;
}

.add-row {
  display: flex;
  gap: 10px;
}

.text-input {
  flex: 1 1 auto;
  min-width: 0;
  padding: 11px 13px;
  border: 1px solid var(--line);
  border-radius: 10px;
  font-size: 15px;
  color: var(--text);
  background: #fbfcfe;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.text-input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(59, 110, 246, 0.15);
  background: #fff;
}

.btn {
  border: none;
  border-radius: 10px;
  padding: 11px 16px;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: background 0.15s ease, transform 0.05s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: var(--primary);
  color: #fff;
  white-space: nowrap;
}

.btn-primary:hover {
  background: var(--primary-dark);
}

.btn-ghost {
  background: #eef1f7;
  color: var(--text);
}

.btn-ghost:hover {
  background: #e2e7f0;
}

.btn-danger {
  background: var(--danger);
  color: #fff;
}

.btn-danger:hover {
  background: #b93a3a;
}

.error-text {
  margin: 10px 0 0;
  color: var(--danger);
  font-size: 13px;
}

.section-title {
  margin: 0 0 10px 4px;
  font-size: 15px;
  font-weight: 600;
  color: var(--muted);
}

.habit-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.habit-item {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--card);
  border-radius: 14px;
  padding: 12px 14px;
  box-shadow: var(--shadow);
  border: 1px solid transparent;
  transition: border-color 0.15s ease, background 0.15s ease;
}

.habit-item.is-done {
  border-color: rgba(23, 166, 115, 0.35);
  background: #f6fdfa;
}

.check-btn {
  flex: 0 0 auto;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  border: 2px solid #c9d2e0;
  background: #fff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  transition: border-color 0.15s ease, background 0.15s ease;
}

.check-btn:hover {
  border-color: var(--success);
}

.habit-item.is-done .check-btn {
  background: var(--success);
  border-color: var(--success);
}

.check-mark {
  width: 14px;
  height: 14px;
  display: block;
  opacity: 0;
  transition: opacity 0.15s ease;
}

.habit-item.is-done .check-mark {
  opacity: 1;
}

.habit-name {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 15px;
  word-break: break-word;
}

.habit-item.is-done .habit-name {
  color: #4a5568;
}

.habit-status {
  flex: 0 0 auto;
  font-size: 12px;
  color: var(--muted);
  white-space: nowrap;
}

.habit-item.is-done .habit-status {
  color: var(--success);
  font-weight: 600;
}

.delete-btn {
  flex: 0 0 auto;
  border: none;
  background: transparent;
  color: #9aa4b5;
  font-size: 13px;
  cursor: pointer;
  padding: 6px 8px;
  border-radius: 8px;
  font-family: inherit;
}

.delete-btn:hover {
  background: #fdecec;
  color: var(--danger);
}

.empty-state {
  background: var(--card);
  border-radius: 16px;
  padding: 32px 20px;
  text-align: center;
  box-shadow: var(--shadow);
}

.empty-title {
  margin: 0 0 6px;
  font-size: 16px;
  font-weight: 600;
}

.empty-desc {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
}

.dialog-mask {
  position: fixed;
  inset: 0;
  background: rgba(20, 26, 36, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-mask[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 340px;
  background: #fff;
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0 18px 40px rgba(20, 26, 36, 0.25);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
}

.dialog-text {
  margin: 0 0 18px;
  color: var(--muted);
  font-size: 14px;
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 380px) {
  .add-row {
    flex-direction: column;
  }
  .btn-primary {
    width: 100%;
  }
}
